function EXTRA(R,ICON){
 /* hook: two spec sheets for one engine */
 const sheet=(x,y,net)=>`<g transform="translate(${x-200} ${y-88})">${IE_box(0,0,400,176,{fill:'#FFFFFF',st:net?ORG:BLU,sw:3,r:18})}${IE_engine(18,30,1,net)}
  ${IE_T(196,40,net?'spec sheet B':'spec sheet A',{fs:22,fw:700,fill:IE_GREY})}${IE_T(196,96,net?'52 kW':'60 kW',{fs:48,fw:800,fill:net?ORG:BLU})}
  ${IE_T(196,132,net?'net: fan, alternator,':'gross: bare engine',{fs:20,fw:700,fill:IE_GREY})}${net?IE_T(196,158,'air cleaner, exhaust',{fs:20,fw:700,fill:IE_GREY}):''}</g>`;
 ICON.ieSheetA=(x,y)=>sheet(x,y,0);
 ICON.ieSheetB=(x,y)=>sheet(x,y,1);
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.ieLevers=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${[['more air',BLU,0,0],['better mixture',CYN,1,0],['less friction',ORG,0,1],['better control',PUR,1,1]].map(([t,col,i,j])=>IE_box(i*214,j*170,206,160,{fill:col,st:col,r:18})+IE_T(i*214+103,j*170+92,t,{fs:26,fw:800,a:'middle',fill:'#FFFFFF'})).join('')}</g>`;
 ICON.ieStandard=(x,y)=>`<g transform="translate(${x-160} ${y-165})">${IE_box(0,0,320,330,{fill:'#FFFFFF',st:ORG,sw:4,r:12})}<rect x="0" y="0" width="320" height="64" rx="12" fill="${ORG}"/>
  ${IE_T(160,44,'ISO 1585',{fs:30,fw:800,a:'middle',fill:'#FFFFFF'})}${IE_T(30,116,'net power',{fs:26,fw:800})}${IE_T(30,166,'25 °C · 99 kPa',{fs:26,fw:700,fill:IE_GREY})}
  ${IE_T(30,216,'P₀ = α × P',{fs:28,fw:800,fill:GRN})}${IE_L(30,262,110,262,IE_IRON,4)}${IE_L(30,292,170,292,IE_IRON,4)}<path d="M228,270 L252,296 L296,240" fill="none" stroke="${GRN}" stroke-width="10" stroke-linecap="round" stroke-linejoin="round"/></g>`;
 ICON.ieTrace=(x,y)=>{const x0=x-190,x1=x+200,y0=y-130,y1=y+130,[px,py]=IE_px(14,62.01,x0,x1,y0,y1);
  return IE_L(x0,y1,x1,y1,IE_GREY,3)+IE_L(x0,y0-20,x0,y1,IE_GREY,3)+IE_trace(IE_MOT,x0,x1,y0,y1,{col:IE_IRON,dash:1,w:3})+IE_trace(IE_FIRE,x0,x1,y0,y1,{col:GRN,w:5})+
   `<circle cx="${px}" cy="${py}" r="9" fill="${GRN}"/>`+IE_T(px+16,py+6,'62 bar',{fs:24,fw:800,fill:GRN})+IE_T(x0+10,y0+4,'p',{fs:24,fw:800,fill:IE_GREY})+IE_T(x1,y1+32,'crank angle',{fs:22,fw:700,a:'end',fill:IE_GREY})+IE_T(x0+14,y1-16,'COV 2.56 %',{fs:24,fw:800,fill:BLU})};
}
